  "titleOrig": "Shopee Thailand raises category commission again Aug 4, fashion accessories to 13.38%（Shopee泰国本土店8月4日更新类目佣金，时尚配饰佣金由11.24%涨至13.38%）",
  "summary": "Shopee泰国本土店8月4日正式更新类目佣金，多个品类上浮1%-2%（不含增值税）：时尚配饰佣金由11.24%涨至13.38%，快消从13.91%涨到16.05%，Mall店铺多数类目涨约2.14%。叠加4月、6月两轮调整，本土店经历三次佣金上调、整体费率涨幅近9%，综合扣点最高可达30%。月销售额低于1万泰铢的小店可享0.5%-1.5%手续费减免。（印选 11-22 热点重排上架：库内真实历史热点复用，非新研究。）",
